-- Disposable fixture tests; no permanent Realtime/submission activity remains.
begin;
create function pg_temp.assert_ok(ok boolean,message text) returns void language plpgsql as $$ begin if ok is distinct from true then raise exception '%',message; end if; end $$;
create function pg_temp.expect_error(statement text) returns void language plpgsql as $$ begin begin execute statement; exception when insufficient_privilege then return; end; raise exception 'Expected access rejection: %',statement; end $$;
insert into auth.users(id) values ('00000000-0000-0000-0000-000000000080'),('00000000-0000-0000-0000-000000000081'),('00000000-0000-0000-0000-000000000082');
update public.profiles set active=true,approval_pending=false where id in ('00000000-0000-0000-0000-000000000080','00000000-0000-0000-0000-000000000081');
update public.profiles set role='admin' where id='00000000-0000-0000-0000-000000000081';
insert into public.events(id,tba_key,year,name,game_slug,created_by) values ('10000000-0000-0000-0000-000000000080','2026presence',2026,'Presence test','2026-rebuilt','00000000-0000-0000-0000-000000000081');
insert into public.teams(team_number,tba_team_key) values(801,'frc801'),(802,'frc802');
insert into public.event_teams(event_id,team_number) values ('10000000-0000-0000-0000-000000000080',801),('10000000-0000-0000-0000-000000000080',802);
insert into public.pit_scouting_submissions(client_submission_id,event_id,team_number,scout_user_id,game_slug,schema_version,game_data,status,completed_at) values ('50000000-0000-0000-0000-000000000080','10000000-0000-0000-0000-000000000080',801,'00000000-0000-0000-0000-000000000081','2026-rebuilt',2,'{}','final',now());
insert into public.pit_scouting_submissions(client_submission_id,event_id,team_number,scout_user_id,game_slug,schema_version,game_data) values ('50000000-0000-0000-0000-000000000082','10000000-0000-0000-0000-000000000080',802,'00000000-0000-0000-0000-000000000081','2026-rebuilt',2,'{}');
insert into realtime.messages(extension,topic) values('presence','fixture'),('broadcast','fixture');
set local role authenticated;
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000080',true);
select set_config('realtime.topic','pit-presence:10000000-0000-0000-0000-000000000080',true);
select pg_temp.assert_ok(public.get_event_pit_completion('10000000-0000-0000-0000-000000000080')='[801]'::jsonb,'Scout reads final existence, excluding drafts');
select pg_temp.assert_ok((select count(*)=0 from public.pit_scouting_submissions),'Other reports remain private');
select pg_temp.assert_ok((select count(*)=1 from realtime.messages),'Only presence receive authorized');
insert into realtime.messages(extension,topic) values('presence','fixture');
select pg_temp.expect_error($s$insert into realtime.messages(extension) values('broadcast')$s$);
select set_config('realtime.topic','pit-presence:not-a-uuid',true);
select pg_temp.assert_ok((select count(*)=0 from realtime.messages),'Malformed topic denied without cast error');
select pg_temp.expect_error($s$insert into realtime.messages(extension) values('presence')$s$);
select set_config('realtime.topic','pit-presence:10000000-0000-0000-0000-000000000080',true);
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000082',true);
select pg_temp.assert_ok((select count(*)=0 from realtime.messages),'Pending scout denied');
select pg_temp.expect_error($s$select public.get_event_pit_completion('10000000-0000-0000-0000-000000000080')$s$);
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000081',true);
update public.events set status='archived' where id='10000000-0000-0000-0000-000000000080';
select pg_temp.assert_ok((select count(*)=0 from realtime.messages),'No live presence in archived events');
select pg_temp.assert_ok(public.get_event_pit_completion('10000000-0000-0000-0000-000000000080')='[801]'::jsonb,'Admin reads archived completion');
select set_config('request.jwt.claim.sub','00000000-0000-0000-0000-000000000080',true);
select pg_temp.expect_error($s$select public.get_event_pit_completion('10000000-0000-0000-0000-000000000080')$s$);
reset role;
select pg_temp.assert_ok((select count(*)=1 from public.scouting_coverage_signal where event_id='10000000-0000-0000-0000-000000000080'),'Pit submission changes invalidate shared completion');
rollback;
